    "a3": "handler_count",
    "v3": "index",
    "v5": "table_base",
    "v6": "entry_id",
    "v7": "entry_offset",
    "v8": "entry_ptr",
    "result": "handler"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "16-bit event/message identifier"
    },
    {
      "offset": 4,
      "meaning": "32-bit handler pointer or associated value"
    }
  ]
